#include "background_correction.hpp"
#include <opencv2/highgui.hpp>
#include <opencv2/imgproc.hpp>

void minMaxBackgroundComputation(cv::Mat& backgroundImage,
    const std::vector<Image>& imageStack)
{
    if (imageStack.size() < 2) {
        throw std::runtime_error("Not enough images for background computation: " +
                                 std::to_string(imageStack.size()));
    }

    try {
        cv::min(imageStack[0].image, imageStack[1].image, backgroundImage);

        cv::Mat temp;
        temp.create(backgroundImage.size(), backgroundImage.type());

        for (size_t i = 1; i < imageStack.size() - 1; ++i) {
            cv::min(imageStack[i].image, imageStack[i + 1].image, temp);
            cv::max(backgroundImage, temp, backgroundImage);
        }
    } catch (const std::exception& e) {
        throw std::runtime_error(
            "Error computing background image:\n" + std::string(e.what()));
    }
}

void backgroundCorrection(std::vector<Image>& imageStack, const Settings& settings)
{
    cv::Mat backgroundImage;

    minMaxBackgroundComputation(backgroundImage, imageStack);

// TODO: currently no way to estimate the quality of the background image

// correction:
#pragma omp parallel for
    for (auto& image : imageStack) {
        cv::absdiff(image.image, backgroundImage, image.image);
    }
}
