    std::vector<Image> imageStack;
    std::unordered_map<size_t, std::vector<cv::Rect>> rois;
    double averageCompression = 0;
    unsigned long long processedFrames = 0;
    auto processStack = [&](std::vector<Image>& stack,
                            const std::vector<FrameMetadata>* metadata,
                            size_t firstFrameIndex,
                            const std::string& frameGroupPrefix,
                            const std::string& sourceFile) {
        if (stack.empty()) return;
        timer.start("Image stack");

        if (settings.normalizeImages) {
#pragma omp parallel for
            for (size_t i = 0; i < stack.size(); i++) {
                cv::normalize(stack[i].image, stack[i].image, 0, 255, cv::NORM_MINMAX);
            }
        }

        backgroundCorrection(stack, settings);
        rois.clear();
        getMergedROIs(rois, stack, settings);
        for (size_t i = 0; i < stack.size(); i++) {
            for (const auto& roi : rois.at(i)) {
                averageCompression += roi.width * roi.height /
                    double(stack[i].image.cols * stack[i].image.rows);
            }
        }

        if (metadata) {
            writer.writeToCheckPointFile(rois, stack, *metadata, firstFrameIndex,
                settings, frameGroupPrefix, sourceFile);
        } else {
            writer.writeToCheckPointFile(rois, stack, files, firstFrameIndex, settings);
        }
        processedFrames += stack.size();
        timer.stop("Image stack");
        handleIncomingLogs(getRank());
    };

    if (hdfReader) {
