    frameSpace.getSimpleExtentDims(dimensions);
    const size_t totalFrames = static_cast<size_t>(dimensions[0]);
    reader.imageHeight = static_cast<size_t>(dimensions[1]);
    reader.imageWidth = static_cast<size_t>(dimensions[2]);
    if (reader.imageWidth == 0 || reader.imageHeight == 0) {
        throw std::runtime_error("HDF5 dataset 'frames' has empty image dimensions");
    }

    const size_t firstToSkip = std::min(settings.skipFirstNImages, totalFrames);
    const size_t afterFirst = totalFrames - firstToSkip;
    const size_t lastToSkip = std::min(settings.skipLastNImages, afterFirst);
    const size_t usableFrames = afterFirst - lastToSkip;
    const size_t rank = getRank();
    const size_t ranks = getSize();
    if (usableFrames == 1) {
        throw std::runtime_error("HDF5 input '" + inputFile +
            "' has only one usable frame; background correction requires at least two");
    }

    const size_t activeRanks = usableFrames == 0
        ? 0
        : std::min(ranks, usableFrames / 2);
    const size_t baseCount = activeRanks == 0 ? 0 : usableFrames / activeRanks;
    const size_t remainder = activeRanks == 0 ? 0 : usableFrames % activeRanks;
    reader.frameCount = rank < activeRanks
        ? baseCount + (rank < remainder ? 1 : 0)
        : 0;
    const size_t rankOffset = rank < activeRanks
        ? rank * baseCount + std::min(rank, remainder)
        : usableFrames;
    reader.firstFrame = firstToSkip + rankOffset;
    reader.nextFrame = 0;

    for (const auto* dataset : {&reader.cameraTimestamps, &reader.frameCounters,
             &reader.timestampsMs}) {
        H5::DataSpace space = dataset->getSpace();
        hsize_t dims[1] = {};
        if (space.getSimpleExtentNdims() != 1 || space.getSimpleExtentDims(dims) < 0 ||
            dims[0] < totalFrames) {
            throw std::runtime_error("HDF5 metadata datasets must be 1D and contain one value per frame");
        }
    }

    printFromAll("reads " + inputFile + " frames " + std::to_string(reader.firstFrame) + " through " +
        std::to_string(reader.frameCount == 0 ? reader.firstFrame :
            reader.firstFrame + reader.frameCount - 1));
